import java.io.*;
import java.util.Scanner;
public class JInputStat2 {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhul ism al-milaff:");
		String name = scan.next();
		JInputStat2 i2 = new JInputStat2();
		i2.getStat(name);
	}
	// Khatwa 1: Ta'reef al-tariqa
	public void getStat(String file_name) {
		// Khatwa 1.1: Ta'reef al-mutaghayyirat allati nahtajuha litaqrir ma3lumat al-milaff
		int numLines = 0;
		String longestLine = "";
		// Khatwa 1.2: Ihit al-kod allathee qad yurmi istithna dakhel qit'at try
		try {
			// Khatwa 1.2.1: Ighlif BufferedReader hawl FileReader
			FileReader fr = new FileReader(file_name); 
			BufferedReader br = new BufferedReader(fr); 
			// Khatwa 1.2.2: Istakhdim al-BufferedReader litaqra satar wahid bi-lwaqt
			String line = null;
			while ( ( line = br.readLine() ) != null) {
				numLines += 1;
				String[] tokens = line.split(" ");
				int numWords = tokens.length;
				// Tahdid in kana al-satr huwa al-atwal hatta al-aan
				if (line.length() > longestLine.length()) {
					longestLine = line;
				}
				// Ijhad tool atwal kalima fi al-satr
				int longestWord = 0;
				for (String w : tokens ) {
					if ( w.length() > longestWord ) {
						longestWord = w.length();
					}
				}
				// Itba3 ma3lumat al-satr
				System.out.println("Satr " + numLines + " fih " + numWords + " kalimat (atwal = " + longestWord + ")");
			}
			System.out.println("Atwal satr:" + longestLine);
			// Khatwa 1.2.3: Eghlaq al-BufferedReader al-murtabit bil-milaff
			br.close();
		}
		// Khatwa 1.3: Ta'amul ma3 kull al-istithna'at al-mumkina allati qad tundar fi qit'at try 
		catch (FileNotFoundException ex) {
			System.out.println("al-milaff lam yujad");
		} catch (IOException ex ) {
			System.out.println("Mushkila ma3 al-milaff!");
		}
	}
}
